package org.traccar.protocol;

import io.netty.handler.codec.LengthFieldBasedFrameDecoder;
import org.traccar.WireProtocolRoot;
import org.traccar.HandlerChainAssembler;
import org.traccar.EndpointListener;
import org.traccar.config.Config;
import org.traccar.model.Command;

import jakarta.inject.Inject;

public class GatorProtocol extends WireProtocolRoot {

    @Inject
    public GatorProtocol(Config config) {
        setSupportedDataCommands(
                Command.TYPE_POSITION_SINGLE,
                Command.TYPE_ENGINE_RESUME,
                Command.TYPE_ENGINE_STOP,
                Command.TYPE_SET_SPEED_LIMIT,
                Command.TYPE_SET_ODOMETER);
        addServer(new EndpointListener(config, getName(), false) {
            @Override
            protected void installChainHandlers(HandlerChainAssembler pipeline, Config config) {
                pipeline.addLast(new LengthFieldBasedFrameDecoder(MAX_FRAME_LENGTH, 3, 2));
                pipeline.addLast(new GatorProtocolEncoder(GatorProtocol.this));
                pipeline.addLast(new GatorProtocolDecoder(GatorProtocol.this));
            }
        });
        addServer(new EndpointListener(config, getName(), true) {
            @Override
            protected void installChainHandlers(HandlerChainAssembler pipeline, Config config) {
                pipeline.addLast(new GatorProtocolDecoder(GatorProtocol.this));
            }
        });
    }

}
